# -*- coding: utf-8 -*-
"""Тексти аркушів 9–11 (модулі, два варіанти) з результатів розкладки і перевірки → pv_norms.json.
Варіант 1 — з проходами і відступами (pv_eval.json, pv_check.json); варіант 2 — максимальний (pv_eval_max.json, pv_check_max.json)."""
import os, json
W = os.path.dirname(os.path.abspath(__file__)) + '/'
K1 = json.load(open(W + 'pv_check.json')); K2 = json.load(open(W + 'pv_check_max.json'))
E1 = json.load(open(W + 'pv_eval.json')); E2 = json.load(open(W + 'pv_eval_max.json'))
nf = lambda v, n=2: (f'{v:,.{n}f}').replace(',', ' ').replace('.', ',')
ni = lambda v: f'{v:,}'.replace(',', ' ')
AM = 2.384 * 1.303; ROOF = 96.62 * 96.59                       # площа модуля і покрівлі в світлі парапетів, м²
def summ(E):
    ur = [m for m in E['roof_mods'] if m['s'] < 0]; uf = [m for m in E['frame_mods'] if m['s'] < 0]
    pw = E['roof']['kwp'] / E['roof']['n']
    lit = dict(n=len(ur) + len(uf), kwp=(len(ur) + len(uf)) * pw, mwh=(sum(m['kwh'] for m in ur) + sum(m['kwh'] for m in uf)) / 1000)
    T = E['total']; return dict(roof=E['roof'], frame=E['frame'], st=T, lit=lit, all=T['n'] + lit['n'], pct=(T['n'] + lit['n']) * AM / ROOF * 100)
S1, S2 = summ(E1), summ(E2)
px = [p for p in K1['paths'] if p['kind'] == 'Пн–Пд']; py = [p for p in K1['paths'] if p['kind'] == 'Сх–Зх']
rows = [
 ['Окремі норми для СЕС на покрівлі', 'ДБН В.1.1-7:2016 — немає; ППБУ зі змінами 2024–2026 — немає; ДБН В.2.6-220:2017 розд. 13 «Розміщення на покритті геліосистем…» — текст не отримано', 'добра практика: IFC 2021 § 1205.3 (США), FK Bauaufsicht 2026 (Німеччина)', '—', '?'],
 ['Обладнання на покритті', 'ДБН В.2.6-220:2017 п. 5.1.3: понад 30 % площі покриття «не допускається»', '—', f"вар. 1 — ≈ {nf(S1['all'] * AM, 0)} м² ≈ {nf(S1['pct'], 0)} %; вар. 2 — ≈ {nf(S2['pct'], 0)} %", '!'],
 ['Відступ від краю покрівлі, стіни, парапету', 'IFC § 1205.3.1: ≥ 1,83 м (обидві осі будівлі > 76,2 м); крайова зона вітру e/10 ≈ 1,6–1,8 м — ДБН В.1.2-2 п. 9.16', '1,83 м з усіх боків', f"Зх {nf(K1['west'])}; Сх {nf(K1['east'])}; Пд {nf(K1['south'])}; Пн {nf(K1['north'])}", '✓'],
 ['Внутрішні проходи', 'IFC § 1205.3.2: через ≤ 45,7 м, ширина ≥ 1,22 м', 'Сх–Зх 2,49 м (через ≈ 31 м); Пн–Пд 1,22 м уздовж ендов осей 7 і 10', f"поля до {nf(K1['field_max_dx'], 1)} × {nf(K1['field_max_dy'], 1)} м", '✓'],
 ['Протипожежні смуги між полями', 'FK Bauaufsicht п. 2.2: поля ≤ 40 м; смуги ≥ 2,5 м (горюча покрівля), ≥ 1,0 м (негорюча)', 'Сх–Зх 2,5 м', f"Сх–Зх {nf(min(p['got'] for p in py))} м; Пн–Пд {nf(min(p['got'] for p in px))}–{nf(max(p['got'] for p in px))} м — залежить від класу ТПО", '?'],
 ['Вихід на дах', 'IFC § 1205.3.2 п. 3: ≥ 1,22 м навколо, прохід до краю', 'зона X 56,6–63,6, Y до 3,8 м', f"до майданчика {nf(K1['exit'], 1)} м, до стійок порталу {nf(K1['portal'], 1)} м", '✓'],
 ['Двері із західної будівлі', 'IFC § 1205.3.2; якщо евакуаційний вихід — ДБН В.1.1-7 п. 7.3.12: шлях ≥ 1,2 м, негорючий верх, огорожа 1,2 м', 'прохід уздовж стіни 1,83 м', f"{nf(K1['door'], 1)} м; чи евакуаційний — з'ясувати", '?'],
 ['Рама кондиціонерів', 'обслуговування — прийнято як прохід IFC 1,22 м', '1,22 м навколо', f"{nf(K1['ac'], 1)} м", '✓'],
 ['Труби вентиляції (11)', 'прийнято 0,5 м від стінки труби', '0,5 м', f"{nf(K1['pipes'])} м", '✓'],
 ['Лівневки, ендови', 'не перекривати шлях води (ДБН В.2.6-220 п. 7.1.3; FM DS 1-15 п. 2.1.5.3)', 'воронки 0,6 м; модулі не перетинають ендов', f"воронки ≥ {nf(K1['drains'], 1)} м; до осі ендови ≥ 0,28 м", '✓'],
 ['Каркаси ліхтарів з модулями', 'поле ≤ 40 м (FK Bauaufsicht), ≤ 45,7 м (IFC)', 'розриви на проходах Сх–Зх', 'сегменти до 28,9 м', '✓'],
 ['Кабелі DC над покрівлею', 'ППБУ розд. IV гл. 1 п. 1.18: заборона зовнішніх проводок над горючими покрівлями', 'закриті металеві лотки', 'врахувати в розділі ЕП', '?'],
 ['Виходи на покрівлю виробничого будинку', 'ДБН В.1.1-7:2016 п. 8.5: один на кожні 200 м периметра', 'периметр ≈ 388 м — потрібно 2', 'відомо: сходи на півдні і двері із західної будівлі', '?'],
 ['Огородження покрівлі', 'ДБН В.1.1-7:2016 п. 8.12 (ухил ≤ 12 %, висота > 10 м)', 'як є', 'Пд, Пн — парапети 1,37–1,65 м; Сх — 0,5 м + огорожа ≈ 1,1 м', '?'],
 ['Перепад висот > 1 м', 'ДБН В.1.1-7:2016 п. 8.8: пожежна драбина', 'як є', 'західна будівля +6,8 м — драбина є (фото 123945)', '✓'],
]
def crows(nm, S):
    return [[f'{nm}: у стрінгах (мережа)', ni(S['st']['n']), nf(S['st']['kwp'], 1), nf(S['st']['mwh'], 1)],
            [f'{nm}: на освітлення (поза стрінгами)', ni(S['lit']['n']), nf(S['lit']['kwp'], 1), nf(S['lit']['mwh'], 1) + '*'],
            [f'{nm}: усього модулів', ni(S['all']), nf(S['st']['kwp'] + S['lit']['kwp'], 1), '']]
compare = crows('Вар. 1 за нормами', S1) + crows('Вар. 2 максимальний', S2) + \
    [['Вар. 2 більше за вар. 1 (у стрінгах)', '+' + ni(S2['st']['n'] - S1['st']['n']), '+' + nf(S2['st']['kwp'] - S1['st']['kwp'], 1), '+' + nf(S2['st']['mwh'] - S1['st']['mwh'], 1)]]
def vnotes_lit(S): return f"Модулі, що не складають стрінг по 11 ({S['lit']['n']} шт.), теж ставляться і підключаються на освітлення цеху (світлодіодне, DC) — рішення власника 28.10. Їх генерація потенційна: використовується в міру навантаження освітлення."
N = dict(
 rows=rows, compare=compare, S1=S1, S2=S2,
 v1_notes=[
  f"Модулі розставлено за правилами арк. 11: відступ 1,83 м від стіни західної будівлі і парапетів, проходи Сх–Зх 2,49 м і Пн–Пд 1,22 м (поля до {nf(K1['field_max_dx'], 1)} × {nf(K1['field_max_dy'], 1)} м), зони навколо виходу, рами кондиціонерів, труб і лівневок. Відступи й проходи перевірено по фактичних модулях.",
  vnotes_lit(S1),
  'На каркасах ліхтарів 13° — книжково, 1 ряд на схил, з розривами на проходах; стрінг — у межах одного ліхтаря.',
  'Генерація — модель v3 (Meteonorm 8.1, тінь від західної будівлі, парапетів, рами, труб і каркасів), стрінги по 11 з утратою від різної освітленості.'],
 v2_notes=[
  f"Максимальний варіант: модулі всюди, де їх фізично можна поставити, без проходів і протипожежних розривів. До стіни західної будівлі і східного парапету — лише край грані ({nf(K2['east'])}–{nf(K2['west'])} м), до південного і північного парапетів {nf(K2['south'])} м. Вільні: вихід на дах з проходом до рами кондиціонерів, двері західної будівлі, рама кондиціонерів (1,0 м), труби (0,3 м), ендови з лівневками.",
  f"Варіант не виконує правил арк. 11 (відступ 1,83 м, проходи через ≤ 45,7 м, поля ≤ 40 м): одне суцільне поле ≈ {nf(K2['field_max_dx'], 0)} × {nf(K2['field_max_dy'], 0)} м; модулі займають ≈ {nf(S2['pct'], 0)} % покрівлі. Потрібне погодження з ДСНС / експертизою. Обслуговування — лише по ендовах (0,56–0,85 м між модулями).",
  vnotes_lit(S2),
  'Каркаси ліхтарів — суцільні, без розривів; стрінг — у межах одного ліхтаря. Генерація — та сама модель v3.'],
 v2_warn=[2],
 sheet10_notes=[
  'Обов\'язкових цифр відступів і проходів для СЕС на покрівлі в Україні не знайдено; прийнято IFC 2021 § 1205.3 і FK Bauaufsicht як добру практику — погодити з ДСНС / експертизою. Розділ 13 ДБН В.2.6-220 отримати й перевірити до РП.',
  f"ДБН В.2.6-220 п. 5.1.3: обладнання понад 30 % площі покриття не допускається, а модулі займають ≈ {nf(S1['pct'], 0)} % (вар. 1) і ≈ {nf(S2['pct'], 0)} % (вар. 2). Потрібна письмова позиція експертизи, чи є модулі «обладнанням» (текст пункту — за карткою e-construction, позначеною «архівна»; звірити з чинною редакцією).",
  'Якщо ліхтарі цеху є частиною системи видалення диму й тепла — закриття їх отворів під каркасами погодити з проєктом протипожежного захисту.',
  'Клас горючості мембрани ТПО невідомий — потрібна декларація Broof(t1) за EN 13501-5. Якщо покрівля горюча: смуги Пн–Пд — 2,5 м (FK Bauaufsicht), кабелі DC — лише в закритих металевих лотках (ППБУ).',
  '«?» — перевірити: виходи на покрівлю (п. 8.5), огородження сходу (п. 8.12), чи двері західної будівлі — евакуаційний вихід (п. 7.3.12). * — потенційна генерація модулів освітлення, якщо освітлення споживає її повністю.'],
 sheet10_warn=[2, 3])
json.dump(N, open(W + 'pv_norms.json', 'w'), ensure_ascii=False, indent=1)
print(json.dumps(dict(S1={k: S1[k] for k in ('lit', 'all', 'pct')}, S2={k: S2[k] for k in ('lit', 'all', 'pct')}), ensure_ascii=False))
for r in compare: print(r)
